import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";

export const fps = 25;

const COLORS = {
  green: "#00C25A",
  white: "#FFFFFF",
  dark: "#1A1A1A",
  bg: "#000000",
};

const TRANSITION = 15;
const SCENE_FRAMES = 750; // 30 seconds at 25fps

const BlackScreen: React.FC = () => (
  <AbsoluteFill style={{ backgroundColor: "transparent" }} />
);

interface PersonCardProps {
  name: string;
  title: string;
  entranceDelay: number;
  align: "left" | "right";
}

const PersonCard: React.FC<PersonCardProps> = ({ name, title, entranceDelay, align }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const containerProgress = spring({
    frame,
    fps,
    delay: entranceDelay,
    config: { damping: 200 },
  });

  const logoProgress = spring({
    frame,
    fps,
    delay: entranceDelay + 15,
    config: { damping: 200 },
  });

  const nameProgress = spring({
    frame,
    fps,
    delay: entranceDelay + 28,
    config: { damping: 200 },
  });

  const lineProgress = spring({
    frame,
    fps,
    delay: entranceDelay + 36,
    config: { damping: 200 },
  });

  const titleProgress = spring({
    frame,
    fps,
    delay: entranceDelay + 43,
    config: { damping: 200 },
  });

  const exitStart = SCENE_FRAMES - 40;
  const exitEnd = SCENE_FRAMES - 5;

  const exitProgress = interpolate(frame, [exitStart, exitEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const entranceY = interpolate(containerProgress, [0, 1], [120, 0]);
  const exitY = interpolate(exitProgress, [0, 1], [0, 120]);
  const containerY = entranceY + exitY;
  const containerOpacity = Math.min(
    containerProgress,
    interpolate(exitProgress, [0, 1], [1, 0])
  );

  const logoOpacity = Math.min(
    logoProgress,
    interpolate(exitProgress, [0, 1], [1, 0])
  );
  const logoX = interpolate(logoProgress, [0, 1], [-30, 0]);

  const nameOpacity = Math.min(
    nameProgress,
    interpolate(exitProgress, [0, 1], [1, 0])
  );
  const nameX = interpolate(nameProgress, [0, 1], [align === "left" ? 40 : -40, 0]);

  const titleOpacity = Math.min(
    titleProgress,
    interpolate(exitProgress, [0, 1], [1, 0])
  );
  const titleX = interpolate(titleProgress, [0, 1], [align === "left" ? 40 : -40, 0]);

  const lineWidth = interpolate(lineProgress, [0, 1], [0, 100]);

  return (
    <div
      style={{
        opacity: containerOpacity,
        transform: `translateY(${containerY}px)`,
        display: "flex",
        flexDirection: "row",
        alignItems: "stretch",
      }}
    >
      <div
        style={{
          backgroundColor: COLORS.dark,
          borderRadius: 14,
          padding: "48px 80px 48px 64px",
          display: "flex",
          flexDirection: "row",
          alignItems: "center",
          gap: 64,
          boxShadow:
            "0 12px 60px rgba(0,0,0,0.6), 0 4px 12px rgba(0,0,0,0.4)",
          whiteSpace: "nowrap",
        }}
      >
        {/* Apify logo */}
        <div
          style={{
            opacity: logoOpacity,
            transform: `translateX(${logoX}px)`,
            display: "flex",
            alignItems: "center",
            flexShrink: 0,
          }}
        >
          <Img
            src={staticFile("assets/apify/Apify Logo white Wordmark.svg")}
            style={{ height: 100, width: "auto" }}
          />
        </div>

        {/* Divider */}
        <div
          style={{
            width: 2,
            alignSelf: "stretch",
            backgroundColor: "rgba(255,255,255,0.15)",
            borderRadius: 2,
            opacity: logoOpacity,
            flexShrink: 0,
          }}
        />

        {/* Name + Title stacked */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: 10,
          }}
        >
          {/* Name */}
          <div
            style={{
              opacity: nameOpacity,
              transform: `translateX(${nameX}px)`,
              fontSize: 64,
              fontWeight: 700,
              color: COLORS.white,
              letterSpacing: "0.01em",
              lineHeight: 1,
              whiteSpace: "nowrap",
            }}
          >
            {name}
          </div>

          {/* Accent line */}
          <div
            style={{
              width: `${lineWidth}%`,
              height: 3,
              backgroundColor: COLORS.green,
              borderRadius: 2,
              opacity: titleOpacity,
            }}
          />

          {/* Job title */}
          <div
            style={{
              opacity: titleOpacity,
              transform: `translateX(${titleX}px)`,
              fontSize: 46,
              fontWeight: 500,
              color: COLORS.green,
              letterSpacing: "0.01em",
              lineHeight: 1,
              whiteSpace: "nowrap",
            }}
          >
            {title}
          </div>
        </div>
      </div>
    </div>
  );
};

const DualNameLower3rd: React.FC = () => {
  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "row",
          alignItems: "flex-end",
          justifyContent: "space-between",
          padding: "0 100px 160px 100px",
        }}
      >
        {/* Left — Luís */}
        <PersonCard
          name="Luís Pinto"
          title="Product Marketing Manager"
          entranceDelay={5}
          align="left"
        />

        {/* Right — Sameh */}
        <PersonCard
          name="Sameh Jarour"
          title="AI Product Evangelist"
          entranceDelay={5}
          align="right"
        />
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// Sequences: 10 + 765 + 25 = 800
// Transitions: 10 + 15 = 25
// Net: 800 - 25 = 775
export const durationInFrames = 775;

const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={10}>
        <BlackScreen />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: 10 })}
      />

      <TransitionSeries.Sequence durationInFrames={SCENE_FRAMES + TRANSITION}>
        <DualNameLower3rd />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={25}>
        <BlackScreen />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
